%[text] correlation ensemble 和Naive比较
ALB=TransferLearning.AudioLightBaseline;
QueryTablePath=TransferLearning.ProjectPath('查询表.xlsx');
LAB=TransferLearning.LightAudioBaseline;
%[text:tableOfContents]{"heading":"**目录**"}
%[text] # A
%[text] 相关性群体
Fig=figure; %[output:7f2871b9]
Layout=tiledlayout(1,2,TileSpacing='tight',Padding='tight'); %[output:7f2871b9]
%[text] 学会阶段相关性群体
EnsembleA=ALB.QueryNTATS(struct(Stimulus="AudioWater",Phase="Learned"),UniExp.Flags.ZScore,1:24,UniExp.Flags.Median);
EnsembleA=EnsembleA(max(EnsembleA.NTATS{:,25:32},[],2)>std(EnsembleA.NTATS{:,1:24},[],2)*3,:);
Normalized=normalize(EnsembleA.NTATS.Data,2,'zscore');
Correlation=corrcoef(Normalized.');
SortIndex=UniExp.CorrelationSort(Correlation);
Correlation=Correlation(SortIndex,SortIndex);
nexttile; %[output:7f2871b9]
imagesc(Correlation); %[output:7f2871b9]
colormap(gray); %[output:7f2871b9]
title('Learned ensemble'); %[output:7f2871b9]
axis off; %[output:7f2871b9]
%[text] 最终阶段相关性群体
EnsembleB=ALB.QueryNTATS(struct(Stimulus="LightWater",Phase="Final"),UniExp.Flags.ZScore,1:24,UniExp.Flags.Median);
EnsembleB=EnsembleB(max(EnsembleB.NTATS{:,25:32},[],2)>std(EnsembleB.NTATS{:,1:24},[],2)*3,:);
Normalized=normalize(EnsembleB.NTATS.Data,2,'zscore');
Correlation=corrcoef(Normalized.');
SortIndex=UniExp.CorrelationSort(Correlation);
Correlation=Correlation(SortIndex,SortIndex);
nexttile; %[output:7f2871b9]
imagesc(Correlation); %[output:7f2871b9]
CB=colorbar; %[output:7f2871b9]
CB.Label.String='Correlation'; %[output:7f2871b9]
colormap(gray); %[output:7f2871b9]
title('Final ensemble'); %[output:7f2871b9]
axis off; %[output:7f2871b9]
MATLAB.Graphics.FigureAspectRatio(8,5,MATLAB.Flags.Narrow); %[output:7f2871b9]
print(Fig,TransferLearning.ProjectPath('Fig3A.svg'),'-dsvg'); %[output:7f2871b9]
%%
%[text] # B
%[text] 各群体交织率
GroupNtats=UniExp.NtatsCellStrip(ALB.QueryNTATS(UniExp.ReadQueryTable(TransferLearning.ProjectPath('查询表.xlsx'),'Fig3B'),UniExp.Flags.ZScore,1:24,UniExp.Flags.Median)); %[output:1fc8aeb7]
EnsembleLogical=max(GroupNtats.NTATS(:,25:32,:),[],2)>std(GroupNtats.NTATS(1:24),[],2).*3;


